import {ToolRegistry} from './registry.js';

describe('tool input validation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#1
  it('returns a required-field rejection before executing', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {name: 'weather', description: 'weather', inputSchema: {type: 'object', required: ['location']}},
      async () => {
        calls++;
        return 'forecast';
      }
    );

    const response = await registry.execute('weather', {});
    expect(response.result).toMatch(/required.*location|location.*required/i);
    expect(calls).toBe(0);
  });
});
